Database.Load:
      var index = 0;
	  var customerPKey = "";
	  var espPKey = "";
      var additionalCond = "";

	  if(Utils.isDefined(jsonQuery.customerPKey)){
        customerPKey =  Utils.convertForDBParam(jsonQuery.customerPKey, "DomPKey");
        additionalCond += "AND cgf_Especialidad_Cuenta__c.cgf_Cuenta__c = #customerPKey# ";
	  }
	  if(Utils.isDefined(jsonQuery.espPKey)){
        espPKey = Utils.convertForDBParam(jsonQuery.espPKey, "DomPKey");
        additionalCond += "AND cgf_Especialidad_Cuenta__c.Id = #espPKey# ";
      }

      var sqlParams = {customerPKey, espPKey};

      var sqlStmt = "SELECT ";
      sqlStmt += "cgf_Especialidad_Cuenta__c.Id AS pKey, ";
      sqlStmt += "cgf_Especialidad_Cuenta__c.Name AS espName, ";
      sqlStmt += "cgf_Especialidad_Cuenta__c.cgf_Cuenta__c AS customerPKey, ";
      sqlStmt += "cgf_Especialidad_Cuenta__c.Id as espPKey ";
      sqlStmt += "FROM cgf_Especialidad_Cuenta__c ";
      sqlStmt += "WHERE ";
      sqlStmt += "cgf_Especialidad_Cuenta__c.IsDeleted = '0' ";
      sqlStmt += additionalCond;
      sqlStmt += "ORDER BY espName ";

      return Utils.replaceMacrosParam(sqlStmt, sqlParams);
